    if kind and not any(z in str(kind).lower() for z in ('interrupted','cancelled')):
     # find tool name via content/result IDs in same file is handled separately below
     pass
   att=o.get('attachment') or {}
   if o.get('type')=='attachment' and str(att.get('type','')).startswith('hook_'):
    key=(str(att.get('hookName')),str(att.get('hookEvent'))); hooks[key]+=1
