import os,glob,json,re,collections,time,shlex
root=os.path.expanduser('~/.claude/projects')
files=[]
for p in glob.glob(root+'/*/*.jsonl'):
 try: files.append((os.path.getmtime(p),p))
 except OSError: pass
files=sorted(files,reverse=True)[:50]
all_tool={}; tool_counts=collections.Counter(); skill_hits=collections.Counter(); slash=collections.Counter(); mcp=collections.Counter(); hooks=collections.Counter(); hook_durs=collections.defaultdict(list); hook_timeout=collections.Counter(); denial=collections.Counter(); denial_kind=collections.defaultdict(collections.Counter); denial_examples={}
for _,p in files:
 records=[]
 try:
  with open(p,errors='replace') as f:
   for line in f:
    try: records.append(json.loads(line))
    except Exception: continue
 except OSError: continue
 for o in records:
  if o.get('type')=='assistant':
   msg=o.get('message') or {}
   for c in msg.get('content') or []:
    if isinstance(c,dict) and c.get('type')=='tool_use':
     tid=c.get('id'); name=str(c.get('name','')); inp=c.get('input') or {}
     if tid: all_tool[tid]=(name,inp)
     tool_counts[name]+=1
     if name=='Skill': skill_hits[str(inp.get('skill'))]+=1
     if name.startswith('mcp__'): mcp[name]+=1
  if o.get('type')=='user':
   txt=(o.get('message') or {}).get('content','')
   if isinstance(txt,str):
    for x in re.findall(r'<command-name>/([^<]+)</command-name>',txt): slash[x]+=1
   kind=o.get('toolDenialKind')
   if kind:
    kinds=str(kind)
    if any(z in kinds.lower() for z in ('interrupted','cancelled')): continue
    # ids can be in toolUseResult, content blocks, or parentToolUseId
    ids=[]
    for k in ('tool_use_id','toolUseId','toolUseID'):
     if o.get(k): ids.append(o[k])
    tur=o.get('toolUseResult') or o.get('tool_result') or {}
    if isinstance(tur,dict):
     for k in ('tool_use_id','toolUseId'):
      if tur.get(k): ids.append(tur[k])
    # also nested content blocks
    cont=(o.get('message') or {}).get('content')
    if isinstance(cont,list):
     for c in cont:
      if isinstance(c,dict) and c.get('tool_use_id'): ids.append(c['tool_use_id'])
    found=None
    for tid in ids:
     if tid in all_tool: found=all_tool[tid]; break
    if found:
     name,inp=found
     if name=='Bash':
      cmd=str(inp.get('command','')).strip(); parts=cmd.split(); key=' '.join(parts[:2]) if len(parts)>=2 else cmd
      # exact invocation candidate
      key='Bash('+cmd+')'
     else: key=name
     denial[key]+=1; denial_kind[key][kinds]+=1; denial_examples.setdefault(key, str((found[1] if isinstance(found[1],dict) else {}))[:160])
  if o.get('type')=='attachment':
   att=o.get('attachment') or {}; typ=str(att.get('type',''))
   if typ.startswith('hook_'):
    key=(str(att.get('hookName')),str(att.get('hookEvent'))); hooks[key]+=1
    if isinstance(att.get('durationMs'),(int,float)): hook_durs[key].append(att['durationMs'])
    if att.get('timedOut') is True: hook_timeout[key]+=1
print('WINDOW',len(files), 'oldest', time.strftime('%Y-%m-%dT%H:%M:%S%z',time.localtime(files[-1][0])) if files else 'n/a', 'newest',time.strftime('%Y-%m-%dT%H:%M:%S%z',time.localtime(files[0][0])) if files else 'n/a')
print('TOOL_COUNTS',json.dumps(tool_counts.most_common(80)))
print('SKILL_HITS',json.dumps(skill_hits))
print('SLASH_HITS',json.dumps(slash))
print('MCP_HITS',json.dumps(mcp))
print('HOOKS',json.dumps({str(k):v for k,v in hooks.items()}))
for k,v in hook_durs.items():
 sv=sorted(v); print('HOOK_DUR',json.dumps({'key':k,'n':len(v),'median':sv[len(sv)//2],'max':max(v),'timeouts':hook_timeout[k]}))
print('DENIALS',json.dumps([{'pattern':k,'count':v,'kinds':dict(denial_kind[k]),'example':denial_examples[k]} for k,v in denial.most_common(80)]))
