import os,glob,re,collections
paths=[]
for base in [os.path.expanduser('~/.claude/agents'),'.claude/agents']:
 for p in glob.glob(base+'/**/*.md',recursive=True): paths.append(p)
print('AGENT_FILES',len(paths))
by=collections.defaultdict(list)
for p in paths:
 lines=open(p,errors='replace').read().splitlines()
 if not lines or lines[0].strip()!='---': continue
 try:end=lines[1:].index('---')+1
 except ValueError:end=-1
 if end<0: print('MALFORMED_FRONTMATTER',p); continue
 fm=lines[1:end]
 name=next((x.split(':',1)[1].strip() for x in fm if x.startswith('name:')),None)
 desc=next((x for x in fm if x.startswith('description:')),None)
 if name:
  if not desc: print('INVALID_AGENT_MISSING_DESCRIPTION',p,'name='+name)
  by[os.path.dirname(p),name].append(p)
for (d,n),ps in by.items():
 if len(ps)>1: print('COLLISION',d,n,len(ps))
print('SKILLS_LOCAL_PROJECT',glob.glob('.claude/skills/*/SKILL.md'))
