namespace SecureId13.State;

/// <summary>
/// A cross-process advisory lock over one SecureId13 state directory, layered on top of an
/// in-process semaphore.
/// </summary>
/// <remarks>
/// <para>
/// Issuance must have exactly one writer at a time, because the next internal identifier is derived
/// from the registry's current length. Two levels of exclusion are used: a <see cref="SemaphoreSlim"/>
/// for threads inside one process, and an exclusively opened lock file for other processes on the
/// same machine.
/// </para>
/// <para>
/// <b>Scope limitation, stated plainly.</b> This is a single-machine mechanism. File locks are not
/// reliable across network filesystems, so a state directory on NFS or SMB shared by several hosts is
/// not protected. For genuine multi-host issuance use one of:
/// </para>
/// <list type="bullet">
///   <item><description>
///   static sharding, by giving each host a distinct <c>InternalIdOffset</c> and a common
///   <c>InternalIdStride</c> equal to the host count, so the hosts allocate from disjoint lanes and
///   need no coordination at all; or
///   </description></item>
///   <item><description>
///   a single issuing service that every application calls; or
///   </description></item>
///   <item><description>
///   an external authoritative store whose atomic reservation is the real serialisation point, and
///   accepting that burned internal identifiers will be more frequent.
///   </description></item>
/// </list>
/// </remarks>
internal sealed class StateDirectoryLock : IDisposable
{
    private readonly SemaphoreSlim _inProcess = new(1, 1);
    private readonly string _lockFilePath;
    private readonly TimeSpan _acquireTimeout;
    private bool _disposed;

    internal StateDirectoryLock(string lockFilePath, TimeSpan acquireTimeout)
    {
        _lockFilePath = lockFilePath;
        _acquireTimeout = acquireTimeout;
    }

    /// <summary>Acquires the lock, waiting up to the configured timeout.</summary>
    /// <param name="cancellationToken">A token that cancels the wait.</param>
    /// <returns>A handle whose disposal releases the lock.</returns>
    /// <exception cref="TimeoutException">The lock could not be acquired in time.</exception>
    internal async ValueTask<Releaser> AcquireAsync(CancellationToken cancellationToken)
    {
        ObjectDisposedException.ThrowIf(_disposed, this);

        if (!await _inProcess.WaitAsync(_acquireTimeout, cancellationToken).ConfigureAwait(false))
        {
            throw new TimeoutException(
                $"Timed out after {_acquireTimeout.TotalSeconds:F0}s waiting for the in-process " +
                "SecureId13 issuance lock.");
        }

        try
        {
            FileStream handle = await AcquireFileLockAsync(cancellationToken).ConfigureAwait(false);
            return new Releaser(this, handle);
        }
        catch
        {
            _inProcess.Release();
            throw;
        }
    }

    /// <summary>Acquires the lock synchronously.</summary>
    /// <param name="cancellationToken">A token that cancels the wait.</param>
    /// <returns>A handle whose disposal releases the lock.</returns>
    /// <exception cref="TimeoutException">The lock could not be acquired in time.</exception>
    internal Releaser Acquire(CancellationToken cancellationToken)
    {
        ObjectDisposedException.ThrowIf(_disposed, this);

        if (!_inProcess.Wait(_acquireTimeout, cancellationToken))
        {
            throw new TimeoutException(
                $"Timed out after {_acquireTimeout.TotalSeconds:F0}s waiting for the in-process " +
                "SecureId13 issuance lock.");
        }

        try
        {
            FileStream handle = AcquireFileLockCore(cancellationToken, asynchronous: false).GetAwaiter().GetResult();
            return new Releaser(this, handle);
        }
        catch
        {
            _inProcess.Release();
            throw;
        }
    }

    /// <summary>Releases the semaphore and deletes nothing; the lock file is intentionally durable.</summary>
    public void Dispose()
    {
        if (_disposed)
        {
            return;
        }

        _disposed = true;
        _inProcess.Dispose();
    }

    private ValueTask<FileStream> AcquireFileLockAsync(CancellationToken cancellationToken) =>
        AcquireFileLockCore(cancellationToken, asynchronous: true);

    private async ValueTask<FileStream> AcquireFileLockCore(CancellationToken cancellationToken, bool asynchronous)
    {
        DateTime deadline = DateTime.UtcNow + _acquireTimeout;
        int backoffMilliseconds = 2;

        while (true)
        {
            cancellationToken.ThrowIfCancellationRequested();

            try
            {
                // FileShare.None is the exclusion primitive: a second process opening the same path
                // with the same share mode fails until this handle is closed.
                return new FileStream(
                    _lockFilePath,
                    FileMode.OpenOrCreate,
                    FileAccess.ReadWrite,
                    FileShare.None,
                    bufferSize: 1,
                    FileOptions.None);
            }
            catch (IOException) when (DateTime.UtcNow < deadline)
            {
                if (asynchronous)
                {
                    await Task.Delay(backoffMilliseconds, cancellationToken).ConfigureAwait(false);
                }
                else
                {
                    Thread.Sleep(backoffMilliseconds);
                }

                backoffMilliseconds = Math.Min(backoffMilliseconds * 2, 100);
            }
            catch (IOException ex)
            {
                throw new TimeoutException(
                    $"Timed out after {_acquireTimeout.TotalSeconds:F0}s waiting for the cross-process " +
                    $"SecureId13 issuance lock '{_lockFilePath}'. Another process is issuing " +
                    "identifiers, or a previous process terminated without releasing the handle.",
                    ex);
            }
        }
    }

    /// <summary>A scope whose disposal releases the state-directory lock.</summary>
    internal readonly struct Releaser : IDisposable
    {
        private readonly StateDirectoryLock _owner;
        private readonly FileStream _handle;

        internal Releaser(StateDirectoryLock owner, FileStream handle)
        {
            _owner = owner;
            _handle = handle;
        }

        /// <summary>Releases the cross-process handle and then the in-process semaphore.</summary>
        public void Dispose()
        {
            _handle.Dispose();
            _owner._inProcess.Release();
        }
    }
}
