-- ---------------------------------------------------------------------------------------------
-- Prerequisites for POST /api/vouchers (docs/examples/create-voucher.json)
--
-- docker/db-init/01-schema.sql creates the WFSSSP schema but seeds no configuration rows, so a
-- create request against a fresh container fails before it ever reaches DocHead:
--
--   CreateVoucherHandler -> VoucherRepository.LoadNumberingPolicyAsync(operationYear: "14", documentTypeCode: 1)
--   returns null unless BOTH of these exist:
--     * _SysYears with OprYear = '14' and a non-null DocNoControlTypeID
--     * DocType  with DocCode = 1
--   -> 400 { "title": "Voucher.NumberingPolicyMissing" }
--
-- Those two rows cannot be inserted on their own: three foreign keys point at lookup tables that
-- the schema script also leaves empty, so the lookups have to be seeded first.
--     _SysYears.DocNoControlTypeID -> DocNoControlType  (FK__SysYears_DocNoGenerateType)
--     DocType.DocGroupCode         -> DocGroup          (FK_DocType_DocGroup)
--     DocType.ValueTypeCode        -> DocValueType      (FK_DocType_DocValyeType)
--
-- Run once against the dev database:
--   docker exec -i wfsssp-sqlserver /opt/mssql-tools18/bin/sqlcmd \
--     -S localhost -U sa -P 'Your_password123!' -C -d WFSSSP \
--     -i /dev/stdin < docs/examples/create-voucher-prerequisites.sql
--
-- Everything below is idempotent.
-- ---------------------------------------------------------------------------------------------
USE [WFSSSP];
GO

SET NOCOUNT ON;
GO

-- ---------------------------------------------------------------------------------------------
-- 1. Lookup rows the foreign keys above require.
--    DocNoControlType mirrors VoucherDocumentNumberControlType
--    (src/Services/Voucher/Voucher.Domain/VoucherNumbering.cs); all five members are seeded so
--    _SysYears.DocNoControlTypeID can be repointed at any of them while testing.
--    DocGroup 1 / DocValueType 1 are the accounting-voucher family the legacy reports key off
--    (see the DocType.ValueTypeCode = 1 filters throughout 01-schema.sql).
-- ---------------------------------------------------------------------------------------------
INSERT INTO dbo.DocNoControlType (DocNoControlTypeID, DocNoControlTypeDesc)
SELECT v.id, v.descr
  FROM (VALUES
            (1, N'سال عملیاتی'),
            (2, N'سال عملیاتی و نوع سند'),
            (3, N'سال عملیاتی و خانواده سند'),
            (4, N'ماه عملیاتی'),
            (9, N'بانک و چک')
       ) AS v(id, descr)
 WHERE NOT EXISTS (SELECT 1 FROM dbo.DocNoControlType t WHERE t.DocNoControlTypeID = v.id);
GO

INSERT INTO dbo.DocGroup (SortIndex, DocGroupCode, DocGroupDesc)
SELECT 1, 1, N'اسناد حسابداری'
 WHERE NOT EXISTS (SELECT 1 FROM dbo.DocGroup WHERE DocGroupCode = 1);
GO

INSERT INTO dbo.DocValueType (ValueTypeCode, ValueTypeDesc)
SELECT 1, N'ریالی'
 WHERE NOT EXISTS (SELECT 1 FROM dbo.DocValueType WHERE ValueTypeCode = 1);
GO

-- ---------------------------------------------------------------------------------------------
-- 2. Operation year '14' (the first two digits of operationMonth "1403").
--    DocNoControlTypeID must be one of VoucherDocumentNumberControlType: 1 = OperationYear,
--    2 = OperationYearAndDocumentType, 3 = OperationYearAndDocumentFamily, 4 = OperationMonth.
--    (9 = BankAndCheque is rejected as NotSupported, and any value outside the enum makes
--    LoadNumberingPolicyAsync throw.)
--    IsClosedOprYear must stay 0, or the create fails with 409 Voucher.OperationYearClosed.
-- ---------------------------------------------------------------------------------------------
IF NOT EXISTS (SELECT 1 FROM dbo._SysYears WHERE OprYear = '14')
BEGIN
    INSERT INTO dbo._SysYears
        (OprYear, IsClosedOprYear, OprYearIsActive, OprMon, LastOprMonFinal, ActiveDate,
         DocNoControlTypeID, VATPercent, VATTaxPercent, VATMunPercent)
    VALUES
        ('14', 0, 1, '1403', 0, '14030101', 2, 9, 6, 3);
END
ELSE
BEGIN
    -- Make an existing row usable rather than leaving a half-configured year behind.
    UPDATE dbo._SysYears
       SET IsClosedOprYear    = 0,
           DocNoControlTypeID = ISNULL(DocNoControlTypeID, 2)
     WHERE OprYear = '14';
END
GO

-- ---------------------------------------------------------------------------------------------
-- 3. Document type 1.
--    GenerateDocNoByStatue = 0 means "the server does not own the document number", which is what
--    lets a request either omit documentNumber (as the examples do) or supply its own 5 digits.
--    With a non-zero value here, sending a documentNumber is rejected with
--    400 Voucher.DocumentNumberIsServerGenerated.
--    Only DocCode / DocDesc / GenerateDocNoByStatue / IsSendToCentral / StatusCodeUpdate are read
--    by this service; the remaining NOT NULL columns are legacy status lists that only the old UI
--    interprets, so empty strings are safe.
-- ---------------------------------------------------------------------------------------------
IF NOT EXISTS (SELECT 1 FROM dbo.DocType WHERE DocCode = 1)
BEGIN
    INSERT INTO dbo.DocType
        (DocCode, DocDesc, UpdateOprMonByStatue, GenerateDocNoByStatue, ControlsDocByStatus,
         NotEditTableByStatus, ValueTypeCode, DocGroupCode, Perfix)
    VALUES
        (1, N'سند تنظیمی (تست)', '', 0, '', '', 1, 1, N'0');
END
ELSE
BEGIN
    UPDATE dbo.DocType SET GenerateDocNoByStatue = 0 WHERE DocCode = 1;
END
GO

-- ---------------------------------------------------------------------------------------------
-- 4. Column-type alignment for _SysYears.
--
--    The legacy schema declares the three VAT columns as [float]; VoucherOperationYearConfiguration
--    maps them as decimal(9,6). EF Core therefore reads them with SqlDataReader.GetDecimal, which
--    does not accept a float column — so simply having a _SysYears row is enough to turn the create
--    request into a 500 (InvalidCastException: Unable to cast System.Double to System.Decimal).
--
--    This widens the columns to match the model, which is the data-side fix. The code-side fix is
--    src/Services/Voucher/Voucher.Persistence/Configurations/VoucherOperationYearConfiguration.cs
--    lines 24-26 — drop the HasColumnType("decimal(9,6)") calls, or change the domain properties to
--    double. Do one or the other; both together are also fine.
--
--    Each of the three columns carries a DEFAULT ((0)) constraint (DF__SysYears_VATPercent and
--    friends). ALTER COLUMN cannot run while a default depends on the column, so the defaults are
--    dropped by lookup — not by hard-coded name, since a database built without the schema
--    script's explicit names would have auto-generated ones — and recreated afterwards.
-- ---------------------------------------------------------------------------------------------
IF EXISTS (SELECT 1
             FROM sys.columns AS c
             JOIN sys.types   AS t ON t.user_type_id = c.user_type_id
            WHERE c.object_id = OBJECT_ID('dbo._SysYears')
              AND c.name = 'VATPercent'
              AND t.name = 'float')
BEGIN
    DECLARE @dropDefaults nvarchar(max) = N'';

    SELECT @dropDefaults = @dropDefaults
                         + N'ALTER TABLE dbo._SysYears DROP CONSTRAINT ' + QUOTENAME(dc.name) + N';'
      FROM sys.default_constraints AS dc
      JOIN sys.columns             AS c ON c.object_id = dc.parent_object_id
                                       AND c.column_id = dc.parent_column_id
     WHERE dc.parent_object_id = OBJECT_ID('dbo._SysYears')
       AND c.name IN ('VATPercent', 'VATTaxPercent', 'VATMunPercent');

    IF @dropDefaults <> N'' EXEC sys.sp_executesql @dropDefaults;

    ALTER TABLE dbo._SysYears ALTER COLUMN VATPercent    decimal(9, 6) NOT NULL;
    ALTER TABLE dbo._SysYears ALTER COLUMN VATTaxPercent decimal(9, 6) NOT NULL;
