    ALTER TABLE dbo._SysYears ALTER COLUMN VATTaxPercent decimal(9, 6) NOT NULL;
    ALTER TABLE dbo._SysYears ALTER COLUMN VATMunPercent decimal(9, 6) NOT NULL;

    ALTER TABLE dbo._SysYears ADD CONSTRAINT DF__SysYears_VATPercent    DEFAULT ((0)) FOR VATPercent;
    ALTER TABLE dbo._SysYears ADD CONSTRAINT DF__SysYears_VATTaxPercent DEFAULT ((0)) FOR VATTaxPercent;
    ALTER TABLE dbo._SysYears ADD CONSTRAINT DF__SysYears_VATMunPercent DEFAULT ((0)) FOR VATMunPercent;
END
GO

