12	using RabbitMQ.Client;
13	using RabbitMQ.Client.Events;
14	
15	namespace Identity.Messaging.RabbitMq;
16	
17	public sealed class RabbitMqOptions
18	{
19	    public const string SectionName = "Identity:Messaging:RabbitMq";
20	    public bool Enabled { get; init; }
21	    public bool ConsumeEnabled { get; init; }
22	    public string ConnectionString { get; init; } = "amqp://guest:guest@localhost:5672/";
23	    public string Exchange { get; init; } = "identity.permission-manifests";
24	    public string Queue { get; init; } = "identity.permission-manifests.identity-service";
25	    public string RoutingKey { get; init; } = "permission.manifest";
26	    public string DeadLetterExchange { get; init; } = "identity.permission-manifests.dlx";
27	    public int RetryCount { get; init; } = 3;
28	}
29	
30	public static class RabbitMqServiceCollectionExtensions
31	{
32	    public static IServiceCollection AddIdentityRabbitMq(this IServiceCollection services, IConfiguration configuration)
33	    {
34	        services.AddOptions<RabbitMqOptions>()
35	            .Bind(configuration.GetSection(RabbitMqOptions.SectionName))
36	            .Validate(x => !x.Enabled || Uri.TryCreate(x.ConnectionString, UriKind.Absolute, out _), "RabbitMQ connection string must be a valid URI when enabled.")
37	            .Validate(x => x.RetryCount is >= 0 and <= 20, "RetryCount must be between 0 and 20.")
38	            .ValidateOnStart();
39	        services.AddSingleton<IIntegrationEventPublisher, RabbitMqIntegrationEventPublisher>();
40	        if (configuration.GetValue<bool>($"{RabbitMqOptions.SectionName}:ConsumeEnabled"))
41	            services.AddHostedService<RabbitMqPermissionManifestConsumer>();
42	        return services;
43	    }
44	}
45	
46	public sealed class RabbitMqIntegrationEventPublisher(
47	    IOptions<RabbitMqOptions> options,
48	    ILogger<RabbitMqIntegrationEventPublisher> logger) : IIntegrationEventPublisher
49	{
50	    private readonly RabbitMqOptions _options = options.Value;
51	    private readonly JsonSerializerOptions _json = new(JsonSerializerDefaults.Web);
52	
53	    public async Task PublishAsync<T>(T message, CancellationToken cancellationToken) where T : class
54	    {
55	        if (!_options.Enabled)
56	            return;
57	
58	        var envelope = message switch
