            return 0;
        return value switch
        {
            byte[] bytes when int.TryParse(Encoding.UTF8.GetString(bytes), out var parsed) => parsed,
            int parsed => parsed,
            long parsed => (int)parsed,
            _ => 0
        };
    }
}

