41	public sealed class EfPermissionRepository(IdentityDbContext db) : IPermissionRepository
42	{
43	    public Task<Permission?> FindByNameAsync(string name, CancellationToken cancellationToken) => db.Permissions.SingleOrDefaultAsync(x => x.Name == name, cancellationToken);
44	    public async Task UpsertManifestAsync(PermissionManifest manifest, CancellationToken cancellationToken)
45	    {
46	        var existingPermissions = await db.Permissions
47	            .Where(x => x.ServiceName == manifest.ServiceName)
48	            .ToListAsync(cancellationToken);
49	        var incomingNames = manifest.Permissions
50	            .Select(x => x.Name)
51	            .ToHashSet(StringComparer.Ordinal);
52	
53	        foreach (var permission in existingPermissions.Where(x => !incomingNames.Contains(x.Name)))
54	            permission.Deprecate();
55	
56	        foreach (var definition in manifest.Permissions)
57	        {
58	            var existing = existingPermissions.SingleOrDefault(x => x.Name == definition.Name);
59	            if (existing is null)
60	                await db.Permissions.AddAsync(new Permission(PermissionId.New(), definition.Name, manifest.ServiceName, definition.Module, definition.Description, manifest.Version, manifest.PublishedAt), cancellationToken);
61	            else
62	                existing.Update(definition.Module, definition.Description, manifest.Version);
63	        }
64	        await db.SaveChangesAsync(cancellationToken);
65	    }
66	    public async Task<IReadOnlyCollection<string>> GetEffectivePermissionsAsync(UserId userId, CancellationToken cancellationToken)
67	    {
68	        var direct = db.UserPermissions
69	            .Where(x => x.UserId == userId)
70	            .Join(db.Permissions.Where(x => !x.IsDeprecated), x => x.PermissionId, x => x.Id, (_, permission) => permission.Name);
71	        var inherited = db.UserRoles
72	            .Where(x => x.UserId == userId)
73	            .Join(db.RolePermissions, x => x.RoleId, x => x.RoleId, (_, rolePermission) => rolePermission.PermissionId)
74	            .Join(db.Permissions.Where(x => !x.IsDeprecated), permissionId => permissionId, permission => permission.Id, (_, permission) => permission.Name);
75	        return await direct.Concat(inherited).Distinct().ToArrayAsync(cancellationToken);
76	    }
77	}

