namespace Identity.Domain;

public readonly record struct UserId(Guid Value)
{
    public static UserId New() => new(Guid.NewGuid());
}

public readonly record struct RoleId(Guid Value)
{
    public static RoleId New() => new(Guid.NewGuid());
}

public readonly record struct PermissionId(Guid Value)
{
    public static PermissionId New() => new(Guid.NewGuid());
}

public sealed class User
{
    private readonly List<UserRole> _roles = [];
    private readonly List<UserPermission> _permissions = [];
    private User() { }

    public User(UserId id, string username, string displayName, DateTimeOffset createdAt)
    {
        if (string.IsNullOrWhiteSpace(username)) throw new ArgumentException("Username is required.", nameof(username));
        Id = id; Username = username.Trim(); DisplayName = displayName.Trim(); CreatedAt = createdAt;
        SecurityStamp = Guid.NewGuid().ToString("N");
    }

    public UserId Id { get; private set; }
    public string Username { get; private set; } = string.Empty;
    public string DisplayName { get; private set; } = string.Empty;
    public bool IsEnabled { get; private set; } = true;
    public int FailedLoginCount { get; private set; }
    public DateTimeOffset? LockedUntil { get; private set; }
    public string SecurityStamp { get; private set; } = string.Empty;
    public DateTimeOffset CreatedAt { get; private set; }
    public DateTimeOffset? UpdatedAt { get; private set; }
    public IReadOnlyCollection<UserRole> Roles => _roles;
    public IReadOnlyCollection<UserPermission> DirectPermissions => _permissions;

    public bool IsLocked(DateTimeOffset now) => LockedUntil is { } until && until > now;
    public void RecordFailedLogin(DateTimeOffset now, int threshold, TimeSpan lockout)
    {
        FailedLoginCount++;
        if (FailedLoginCount >= threshold) LockedUntil = now.Add(lockout);
        UpdatedAt = now;
    }
    public void RecordSuccessfulLogin(DateTimeOffset now) { FailedLoginCount = 0; LockedUntil = null; UpdatedAt = now; }
    public void Disable(DateTimeOffset now) { IsEnabled = false; UpdatedAt = now; }
    public void Enable(DateTimeOffset now) { IsEnabled = true; UpdatedAt = now; }
    public void RotateSecurityStamp(DateTimeOffset now) { SecurityStamp = Guid.NewGuid().ToString("N"); UpdatedAt = now; }
    public void AssignRole(RoleId roleId, DateTimeOffset now) { if (_roles.All(x => x.RoleId != roleId)) _roles.Add(new UserRole(Id, roleId, now)); UpdatedAt = now; }
    public void GrantPermission(PermissionId permissionId, DateTimeOffset now) { if (_permissions.All(x => x.PermissionId != permissionId)) _permissions.Add(new UserPermission(Id, permissionId, now)); UpdatedAt = now; }
}

