public sealed class Permission
{
    private Permission() { }
    public Permission(PermissionId id, string name, string serviceName, string module, string description, string version, DateTimeOffset registeredAt)
    {
        if (string.IsNullOrWhiteSpace(name) || name.Length > 200) throw new ArgumentException("A stable permission name is required.", nameof(name));
        Id = id; Name = name.Trim(); ServiceName = serviceName.Trim(); Module = module.Trim(); Description = description.Trim(); Version = version.Trim(); RegisteredAt = registeredAt;
    }
    public PermissionId Id { get; private set; }
    public string Name { get; private set; } = string.Empty;
