    public void Dispose()
    {
        foreach (var rsa in rsaKeys)
            rsa.Dispose();
        rsaKeys.Clear();
    }

    private RsaSecurityKey CreateKey(PersistedSigningKey record)
    {
        var rsa = RSA.Create();
        rsa.ImportPkcs8PrivateKey(Convert.FromBase64String(record.PrivateKey), out _);
