            .Where(x => x.RetireAt is null || x.RetireAt > now)
            .GroupBy(x => x.KeyId, StringComparer.Ordinal)
            .Select(x => x.OrderByDescending(key => key.CreatedAt).First())
            .ToList();

        var active = records
            .Where(x => x.RetireAt is null)
            .OrderByDescending(x => x.CreatedAt)
            .FirstOrDefault();

