68	public sealed class JwtSigningKeyProvider : IDisposable
69	{
70	    private readonly List<RSA> rsaKeys = [];
71	
72	    public JwtSigningKeyProvider(IConfiguration configuration)
73	    {
74	        ArgumentNullException.ThrowIfNull(configuration);
75	        Issuer = configuration["Identity:Tokens:Issuer"] ?? "https://localhost:7001";
76	        Audience = configuration["Identity:Tokens:Audience"] ?? "identity-api";
77	        var options = new JwtSigningKeyOptions
78	        {
79	            StoragePath = configuration["Identity:Tokens:StoragePath"] ?? "identity-signing-keys.json",
80	            KeyId = configuration["Identity:Tokens:KeyId"] ?? "development-key-1",
81	            KeySize = ParsePositiveInt(configuration["Identity:Tokens:KeySize"], 2048),
82	            ActiveKeyLifetime = ParseDuration(configuration["Identity:Tokens:ActiveKeyLifetime"], TimeSpan.FromDays(30)),
83	            KeyOverlapLifetime = ParseDuration(configuration["Identity:Tokens:KeyOverlapLifetime"], TimeSpan.FromDays(14)),
84	            AutomaticRotation = ParseBool(configuration["Identity:Tokens:AutomaticRotation"], true)
85	        };
86	        Validate(options);
87	        var records = LoadOrCreate(options, DateTimeOffset.UtcNow);
88	        var active = records.Single(x => x.RetireAt is null);
89	        KeyId = active.KeyId;
90	        Key = CreateKey(active);
91	        PublicKeys = records
92	            .Select(CreatePublicKey)
93	            .OrderBy(x => x.KeyId, StringComparer.Ordinal)
94	            .ToArray();
95	    }
96	
97	    public string Issuer { get; }
98	    public string Audience { get; }
99	    public string KeyId { get; }
100	    public RsaSecurityKey Key { get; }
101	    public IReadOnlyCollection<RsaSecurityKey> PublicKeys { get; }
102	    public RsaSecurityKey PublicKey => PublicKeys.Single(x => x.KeyId == KeyId);
103	
104	    public void Dispose()
105	    {
106	        foreach (var rsa in rsaKeys)
107	            rsa.Dispose();
108	        rsaKeys.Clear();
109	    }
110	
111	    private RsaSecurityKey CreateKey(PersistedSigningKey record)
112	    {
113	        var rsa = RSA.Create();
114	        rsa.ImportPkcs8PrivateKey(Convert.FromBase64String(record.PrivateKey), out _);
115	        rsaKeys.Add(rsa);
116	        return new RsaSecurityKey(rsa) { KeyId = record.KeyId };
117	    }
118	
119	    private RsaSecurityKey CreatePublicKey(PersistedSigningKey record)
120	    {
121	        using var rsa = RSA.Create();
122	        rsa.ImportPkcs8PrivateKey(Convert.FromBase64String(record.PrivateKey), out _);
123	        return new RsaSecurityKey(rsa.ExportParameters(false)) { KeyId = record.KeyId };
124	    }
125	
126	    private static List<PersistedSigningKey> LoadOrCreate(JwtSigningKeyOptions options, DateTimeOffset now)
127	    {
128	        var path = Path.GetFullPath(options.StoragePath);
129	        var directory = Path.GetDirectoryName(path);
130	        if (!string.IsNullOrWhiteSpace(directory))
131	            Directory.CreateDirectory(directory);
132	
133	        List<PersistedSigningKey> records;
134	        if (File.Exists(path))
135	        {
136	            try
137	            {
138	                records = JsonSerializer.Deserialize<List<PersistedSigningKey>>(File.ReadAllText(path)) ?? [];
139	            }
140	            catch (Exception exception) when (exception is JsonException or IOException or UnauthorizedAccessException)
141	            {
142	                throw new InvalidOperationException($"JWT signing-key store could not be read: {path}", exception);
143	            }
144	        }
145	        else
146	        {
147	            records = [];
148	        }
149	
150	        records = records
151	            .Where(x => x.RetireAt is null || x.RetireAt > now)
152	            .GroupBy(x => x.KeyId, StringComparer.Ordinal)
153	            .Select(x => x.OrderByDescending(key => key.CreatedAt).First())
154	            .ToList();
155	
156	        var active = records
157	            .Where(x => x.RetireAt is null)
158	            .OrderByDescending(x => x.CreatedAt)
159	            .FirstOrDefault();
160	
161	        if (active is null)
162	        {
163	            active = CreatePersistedKey(options.KeyId, options.KeySize, now);
164	            records.Add(active);
165	        }
166	        else if (options.AutomaticRotation && now - active.CreatedAt >= options.ActiveKeyLifetime)
167	        {
168	            active.RetireAt = now.Add(options.KeyOverlapLifetime);
169	            var rotatedId = $"{options.KeyId}-{now:yyyyMMddHHmmss}-{Guid.NewGuid():N}";
170	            records.Add(CreatePersistedKey(rotatedId, options.KeySize, now));
171	        }
172	
173	        Persist(path, records);
174	        return records;
175	    }
176	
177	    private static PersistedSigningKey CreatePersistedKey(string keyId, int keySize, DateTimeOffset createdAt)
178	    {
179	        using var rsa = RSA.Create(keySize);
180	        return new PersistedSigningKey(
181	            keyId,
182	            createdAt,
183	            null,
184	            Convert.ToBase64String(rsa.ExportPkcs8PrivateKey()));
185	    }
186	
187	    private static void Persist(string path, IReadOnlyCollection<PersistedSigningKey> records)
188	    {
189	        var temporaryPath = $"{path}.{Guid.NewGuid():N}.tmp";
190	        try
191	        {
192	            var json = JsonSerializer.Serialize(records, new JsonSerializerOptions { WriteIndented = true });
193	            File.WriteAllText(temporaryPath, json);
194	            File.Move(temporaryPath, path, overwrite: true);
195	            if (!OperatingSystem.IsWindows())
196	                File.SetUnixFileMode(path, UnixFileMode.UserRead | UnixFileMode.UserWrite);
197	        }
198	        finally
199	        {
200	            if (File.Exists(temporaryPath))
201	                File.Delete(temporaryPath);
202	        }
203	    }
204	
205	    private static void Validate(JwtSigningKeyOptions options)
206	    {
207	        if (string.IsNullOrWhiteSpace(options.StoragePath)) throw new InvalidOperationException("JWT signing-key storage path is required.");
208	        if (string.IsNullOrWhiteSpace(options.KeyId)) throw new InvalidOperationException("JWT signing-key ID is required.");
209	        if (options.KeySize < 2048) throw new InvalidOperationException("JWT signing keys must be at least 2048 bits.");
210	        if (options.ActiveKeyLifetime <= TimeSpan.Zero) throw new InvalidOperationException("JWT active-key lifetime must be positive.");
211	        if (options.KeyOverlapLifetime <= TimeSpan.Zero) throw new InvalidOperationException("JWT key-overlap lifetime must be positive.");
212	    }
213	
214	    private static int ParsePositiveInt(string? value, int fallback)
215	        => int.TryParse(value, out var result) && result > 0 ? result : fallback;
216	
217	    private static bool ParseBool(string? value, bool fallback)
218	        => bool.TryParse(value, out var result) ? result : fallback;
219	
220	    private static TimeSpan ParseDuration(string? value, TimeSpan fallback)
221	        => TimeSpan.TryParse(value, out var result) && result > TimeSpan.Zero ? result : fallback;
222	
223	    private sealed class PersistedSigningKey(string keyId, DateTimeOffset createdAt, DateTimeOffset? retireAt, string privateKey)
224	    {
225	        public string KeyId { get; } = keyId;
226	        public DateTimeOffset CreatedAt { get; } = createdAt;
227	        public DateTimeOffset? RetireAt { get; set; } = retireAt;
228	        public string PrivateKey { get; } = privateKey;
229	    }
230	}
