123	public sealed class RabbitMqPermissionManifestConsumer(
124	    IOptions<RabbitMqOptions> options,
125	    IServiceScopeFactory scopeFactory,
126	    ILogger<RabbitMqPermissionManifestConsumer> logger) : BackgroundService
127	{
128	    private const string RetryHeader = "x-identity-retry-count";
129	    private readonly RabbitMqOptions _options = options.Value;
130	    private readonly JsonSerializerOptions _json = new(JsonSerializerDefaults.Web);
131	
132	    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
133	    {
134	        while (!stoppingToken.IsCancellationRequested)
135	        {
136	            try
137	            {
138	                await ConsumeConnectionAsync(stoppingToken);
139	            }
140	            catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested) { }
141	            catch (Exception exception)
142	            {
143	                logger.LogWarning(exception, "RabbitMQ consumer unavailable; retrying without stopping the service.");
144	                try { await Task.Delay(TimeSpan.FromSeconds(5), stoppingToken); }
145	                catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested) { }
146	            }
147	        }
148	    }
149	
150	    private async Task ConsumeConnectionAsync(CancellationToken cancellationToken)
151	    {
152	        var factory = new ConnectionFactory
153	        {
154	            Uri = new Uri(_options.ConnectionString),
155	            ClientProvidedName = "identity-service-consumer"
156	        };
157	        await using var connection = await factory.CreateConnectionAsync(cancellationToken);
158	        await using var channel = await connection.CreateChannelAsync(cancellationToken: cancellationToken);
159	        await RabbitMqTopology.DeclareAsync(channel, _options, cancellationToken);
160	        await channel.BasicQosAsync(0, 1, false, cancellationToken);
161	
162	        var consumer = new AsyncEventingBasicConsumer(channel);
163	        consumer.ReceivedAsync += async (_, delivery) => await HandleAsync(channel, delivery, cancellationToken);
164	        await channel.BasicConsumeAsync(_options.Queue, autoAck: false, consumer, cancellationToken);
165	        await Task.Delay(Timeout.InfiniteTimeSpan, cancellationToken);
166	    }
