168	    private async Task HandleAsync(IChannel channel, BasicDeliverEventArgs delivery, CancellationToken cancellationToken)
169	    {
170	        try
171	        {
172	            var message = JsonSerializer.Deserialize<PermissionManifestEvent>(delivery.Body.Span, _json);
173	            if (message is null || message.SchemaVersion != 1 || string.IsNullOrWhiteSpace(message.ServiceId) || string.IsNullOrWhiteSpace(message.ServiceName))
174	                throw new InvalidDataException("Invalid permission-manifest event.");
175	
176	            await using var scope = scopeFactory.CreateAsyncScope();
177	            var synchronizer = scope.ServiceProvider.GetRequiredService<PermissionManifestSynchronizer>();
178	            var accepted = await synchronizer.SynchronizeAsync(PermissionManifestEventMapper.ToApplicationManifest(message), cancellationToken);
179	            logger.LogDebug("Permission manifest event {EventId} was {Result}.", message.EventId, accepted ? "accepted" : "ignored as duplicate");
