181	        }
182	        catch (Exception exception) when (exception is JsonException or InvalidDataException or ArgumentException)
183	        {
184	            logger.LogWarning(exception, "Rejecting malformed permission-manifest message {DeliveryTag}.", delivery.DeliveryTag);
185	            await channel.BasicRejectAsync(delivery.DeliveryTag, requeue: false, cancellationToken);
186	        }
187	        catch (Exception exception)
188	        {
189	            var retryCount = GetRetryCount(delivery.BasicProperties);
190	            if (retryCount >= _options.RetryCount)
191	            {
192	                logger.LogError(exception, "Permission-manifest processing failed after {RetryCount} retries for {DeliveryTag}; moving to dead letter queue.", retryCount, delivery.DeliveryTag);
193	                await channel.BasicRejectAsync(delivery.DeliveryTag, requeue: false, cancellationToken);
194	                return;
195	            }
196	
197	            logger.LogWarning(exception, "Permission-manifest processing failed for {DeliveryTag}; scheduling retry {RetryCount}.", delivery.DeliveryTag, retryCount + 1);
198	            var properties = new BasicProperties
199	            {
200	                ContentType = delivery.BasicProperties.ContentType,
201	                DeliveryMode = DeliveryModes.Persistent,
202	                MessageId = delivery.BasicProperties.MessageId,
203	                CorrelationId = delivery.BasicProperties.CorrelationId,
204	                Type = delivery.BasicProperties.Type,
205	                Headers = new Dictionary<string, object?> { [RetryHeader] = retryCount + 1 }
206	            };
207	            await channel.BasicPublishAsync(_options.RetryExchange, _options.Queue, true, properties, delivery.Body, cancellationToken);
208	            await channel.BasicAckAsync(delivery.DeliveryTag, multiple: false, cancellationToken);
209	        }
210	    }
211	
212	    private static int GetRetryCount(IReadOnlyBasicProperties properties)
213	    {
214	        if (properties.Headers is null || !properties.Headers.TryGetValue(RetryHeader, out var value))
215	            return 0;
216	        return value switch
217	        {
218	            byte[] bytes when int.TryParse(Encoding.UTF8.GetString(bytes), out var parsed) => parsed,
219	            int parsed => parsed,
220	            long parsed => (int)parsed,
221	            _ => 0
222	        };
223	    }
224	}
