73	    ISystemClock clock)
74	{
75	    public async Task<AuthenticationResult> LoginAsync(string username, string password, CancellationToken cancellationToken)
76	    {
77	        var user = await users.FindByUsernameAsync(username.Trim(), cancellationToken);
78	        if (user is null || !user.IsEnabled) return AuthenticationResult.Failure("invalid_credentials");
79	        if (user.IsLocked(clock.UtcNow)) return AuthenticationResult.Failure("account_locked");
80	        var credential = await credentials.FindAsync(user.Id, cancellationToken);
81	        if (credential is null || !passwordVerifier.Verify(credential.PasswordHash, password))
