syntax = "proto3";

option csharp_namespace = "Company.Identity.Grpc";
package company.identity.v1;

import "google/protobuf/timestamp.proto";

service IdentityService {
  rpc Login (LoginRequest) returns (TokenResponse);
  rpc Refresh (RefreshRequest) returns (TokenResponse);
  rpc Logout (LogoutRequest) returns (LogoutResponse);
  rpc GetCurrentUser (CurrentUserRequest) returns (CurrentUserResponse);
}

message LoginRequest {
  string username = 1;
  string password = 2;
}

message RefreshRequest {
  string refresh_token = 1;
}

message LogoutRequest {
  string session_id = 1;
}

message LogoutResponse {}
message CurrentUserRequest {}

message TokenResponse {
  string access_token = 1;
  string refresh_token = 2;
  google.protobuf.Timestamp expires_at = 3;
  string session_id = 4;
}

message CurrentUserResponse {
  string user_id = 1;
  string username = 2;
  string display_name = 3;
  repeated string roles = 4;
  repeated string permissions = 5;
  string session_id = 6;
}
using Identity.Application;
using Identity.Domain;
namespace Identity.Application.Tests;
public class ApplicationTests
{
    [Fact]
    public async Task Permission_evaluator_uses_effective_permissions()
    {
        var repo = new FakePermissionRepository(["Orders.Read"]);
        var service = new PermissionAuthorizationService(repo);
        Assert.True(await service.HasPermissionAsync(UserId.New(), "Orders.Read", default));
        Assert.False(await service.HasPermissionAsync(UserId.New(), "Orders.Delete", default));
    }
    private sealed class FakePermissionRepository(IReadOnlyCollection<string> values) : IPermissionRepository
    {
        public Task<Permission?> FindByNameAsync(string name, CancellationToken cancellationToken) => Task.FromResult<Permission?>(null);
        public Task UpsertManifestAsync(PermissionManifest manifest, CancellationToken cancellationToken) => Task.CompletedTask;
        public Task<IReadOnlyCollection<string>> GetEffectivePermissionsAsync(UserId userId, CancellationToken cancellationToken) => Task.FromResult(values);
    }
}

public sealed class SessionLifecycleTests
{
    [Fact]
    public async Task Logout_all_revokes_only_active_sessions()
    {
        var now = new DateTimeOffset(2026, 1, 1, 0, 0, 0, TimeSpan.Zero);
        var user = new User(UserId.New(), "user", "User", now);
        var active = new UserSession(Guid.NewGuid(), user.Id, now, now.AddHours(1), user.SecurityStamp);
        var expired = new UserSession(Guid.NewGuid(), user.Id, now.AddHours(-2), now.AddMinutes(-1), user.SecurityStamp);
        var sessions = new FakeSessionStore(active, expired);
        var service = new LocalAuthenticationService(
            new EmptyUserRepository(), new EmptyCredentialStore(), new EmptyPermissionRepository(), sessions,
            new EmptyRefreshTokenStore(), new EmptyPasswordVerifier(), new EmptyTokenIssuer(), new FixedClock(now));

        var revoked = await service.LogoutAllAsync(user.Id, CancellationToken.None);

        Assert.Equal(1, revoked);
        Assert.NotNull(active.RevokedAt);
        Assert.Null(expired.RevokedAt);
    }

    private sealed class FixedClock(DateTimeOffset now) : ISystemClock { public DateTimeOffset UtcNow => now; }
    private sealed class FakeSessionStore(params UserSession[] values) : ISessionStore
    {
        private readonly List<UserSession> sessions = [.. values];
        public Task AddAsync(UserSession session, CancellationToken cancellationToken) => Task.CompletedTask;
        public Task<UserSession?> FindAsync(Guid id, CancellationToken cancellationToken) => Task.FromResult(sessions.SingleOrDefault(x => x.Id == id));
        public Task<IReadOnlyCollection<UserSession>> FindForUserAsync(UserId userId, CancellationToken cancellationToken)
            => Task.FromResult<IReadOnlyCollection<UserSession>>(sessions.Where(x => x.UserId == userId).ToArray());
        public Task RevokeAsync(UserSession session, DateTimeOffset at, CancellationToken cancellationToken) { session.Revoke(at); return Task.CompletedTask; }
    }
    private sealed class EmptyUserRepository : IUserRepository
    {
        public Task<User?> FindByUsernameAsync(string username, CancellationToken cancellationToken) => Task.FromResult<User?>(null);
        public Task<User?> FindAsync(UserId id, CancellationToken cancellationToken) => Task.FromResult<User?>(null);
        public Task AddAsync(User user, CancellationToken cancellationToken) => Task.CompletedTask;
        public Task SaveAsync(User user, CancellationToken cancellationToken) => Task.CompletedTask;
    }
    private sealed class EmptyCredentialStore : IPasswordCredentialStore
    {
        public Task<PasswordCredential?> FindAsync(UserId userId, CancellationToken cancellationToken) => Task.FromResult<PasswordCredential?>(null);
        public Task SaveAsync(PasswordCredential credential, CancellationToken cancellationToken) => Task.CompletedTask;
    }
    private sealed class EmptyPermissionRepository : IPermissionRepository
    {
        public Task<Permission?> FindByNameAsync(string name, CancellationToken cancellationToken) => Task.FromResult<Permission?>(null);
        public Task UpsertManifestAsync(PermissionManifest manifest, CancellationToken cancellationToken) => Task.CompletedTask;
        public Task<IReadOnlyCollection<string>> GetEffectivePermissionsAsync(UserId userId, CancellationToken cancellationToken) => Task.FromResult<IReadOnlyCollection<string>>([]);
    }
    private sealed class EmptyRefreshTokenStore : IRefreshTokenStore
    {
        public Task<RefreshTokenRecord?> FindAsync(string tokenHash, CancellationToken cancellationToken) => Task.FromResult<RefreshTokenRecord?>(null);
        public Task AddAsync(RefreshTokenRecord record, CancellationToken cancellationToken) => Task.CompletedTask;
        public Task RotateAsync(RefreshTokenRecord current, RefreshTokenRecord replacement, CancellationToken cancellationToken) => Task.CompletedTask;
        public Task RevokeFamilyAsync(string familyId, DateTimeOffset revokedAt, CancellationToken cancellationToken) => Task.CompletedTask;
    }
    private sealed class EmptyPasswordVerifier : IPasswordVerifier
    {
        public bool Verify(string encodedHash, string password) => false;
        public string Hash(string password) => string.Empty;
    }
    private sealed class EmptyTokenIssuer : IAccessTokenIssuer
    {
        public Task<AccessTokenResult> IssueAsync(User user, IReadOnlyCollection<string> permissions, Guid sessionId, CancellationToken cancellationToken)
            => throw new NotSupportedException();
    }
}
using Identity.Api;
using Identity.Application;
using Identity.Domain;

namespace Identity.Api.Tests;

public sealed class BffSessionValidatorTests
{
    private static readonly DateTimeOffset Now = new(2026, 1, 1, 0, 0, 0, TimeSpan.Zero);

    [Fact]
    public async Task Active_session_for_enabled_user_is_valid()
    {
        var user = new User(UserId.New(), "user", "User", Now);
        var session = new UserSession(Guid.NewGuid(), user.Id, Now, Now.AddHours(1), user.SecurityStamp);
        var validator = new BffSessionValidator(
            new FakeSessionStore(session),
            new FakeUserRepository(user),
            new FixedClock());

        Assert.True(await validator.ValidateAsync(session.Id.ToString(), CancellationToken.None));
    }

    [Fact]
    public async Task Revoked_session_is_invalid()
    {
        var user = new User(UserId.New(), "user", "User", Now);
        var session = new UserSession(Guid.NewGuid(), user.Id, Now, Now.AddHours(1), user.SecurityStamp);
        session.Revoke(Now);
        var validator = new BffSessionValidator(
            new FakeSessionStore(session),
            new FakeUserRepository(user),
            new FixedClock());

        Assert.False(await validator.ValidateAsync(session.Id.ToString(), CancellationToken.None));
    }

    [Fact]
    public async Task Security_stamp_change_invalidates_session()
    {
        var user = new User(UserId.New(), "user", "User", Now);
        var session = new UserSession(Guid.NewGuid(), user.Id, Now, Now.AddHours(1), user.SecurityStamp);
        user.RotateSecurityStamp(Now);
        var validator = new BffSessionValidator(
            new FakeSessionStore(session),
            new FakeUserRepository(user),
            new FixedClock());

        Assert.False(await validator.ValidateAsync(session.Id.ToString(), CancellationToken.None));
    }

    [Fact]
    public async Task Invalid_session_id_does_not_query_persistence()
    {
        var sessions = new FakeSessionStore();
        var validator = new BffSessionValidator(sessions, new FakeUserRepository(), new FixedClock());

        Assert.False(await validator.ValidateAsync("not-a-guid", CancellationToken.None));
        Assert.Equal(0, sessions.FindCount);
    }

    private sealed class FixedClock : ISystemClock
    {
        public DateTimeOffset UtcNow => Now;
    }

    private sealed class FakeSessionStore(params UserSession[] initial) : ISessionStore
    {
        private readonly Dictionary<Guid, UserSession> sessions = initial.ToDictionary(x => x.Id);
        public int FindCount { get; private set; }

        public Task AddAsync(UserSession session, CancellationToken cancellationToken)
        {
            sessions[session.Id] = session;
            return Task.CompletedTask;
        }

        public Task<IReadOnlyCollection<UserSession>> FindForUserAsync(UserId userId, CancellationToken cancellationToken)
            => Task.FromResult<IReadOnlyCollection<UserSession>>(sessions.Values.Where(x => x.UserId == userId).ToArray());

        public Task<UserSession?> FindAsync(Guid id, CancellationToken cancellationToken)
        {
            FindCount++;
            sessions.TryGetValue(id, out var session);
            return Task.FromResult(session);
        }

        public Task RevokeAsync(UserSession session, DateTimeOffset at, CancellationToken cancellationToken)
        {
            session.Revoke(at);
            return Task.CompletedTask;
        }
    }

    private sealed class FakeUserRepository(params User[] initial) : IUserRepository
    {
        private readonly Dictionary<UserId, User> users = initial.ToDictionary(x => x.Id);

        public Task<User?> FindByUsernameAsync(string username, CancellationToken cancellationToken)
            => Task.FromResult<User?>(null);

        public Task<User?> FindAsync(UserId id, CancellationToken cancellationToken)
        {
            users.TryGetValue(id, out var user);
            return Task.FromResult(user);
        }

        public Task AddAsync(User user, CancellationToken cancellationToken)
        {
            users[user.Id] = user;
            return Task.CompletedTask;
        }

        public Task SaveAsync(User user, CancellationToken cancellationToken)
            => Task.CompletedTask;
    }
}

