using System.Security.Claims;
using Identity.Application;

namespace Identity.Api;

public sealed class HttpCurrentUserContext(
    IHttpContextAccessor accessor,
    ISystemClock clock) : ICurrentUserContext
{
    private ClaimsPrincipal Principal => accessor.HttpContext?.User ?? new ClaimsPrincipal(new ClaimsIdentity());

    public bool IsAuthenticated => Principal.Identity?.IsAuthenticated == true;
    public Guid? UserId => Guid.TryParse(Principal.FindFirstValue("sub"), out var value) ? value : null;
    public string? Username => Principal.Identity?.Name ?? Principal.FindFirstValue("unique_name");
    public string? DisplayName => Principal.FindFirstValue("name") ?? Username;
    public IReadOnlyCollection<string> Roles => Principal
        .FindAll(ClaimTypes.Role)
        .Concat(Principal.FindAll("role"))
        .Concat(Principal.FindAll("roles"))
        .Select(x => x.Value)
        .Distinct(StringComparer.Ordinal)
        .ToArray();
    public IReadOnlyCollection<string> Permissions => Principal
        .FindAll("permission")
        .Concat(Principal.FindAll("permissions"))
        .Select(x => x.Value)
        .Distinct(StringComparer.Ordinal)
        .ToArray();
    public string? SessionId => Principal.FindFirstValue("sid");
    public DateTimeOffset RequestDateTime => clock.UtcNow;
}
using Company.Identity.Authorization;
using Microsoft.AspNetCore.Authorization;
using Microsoft.Extensions.DependencyInjection;
namespace Company.Identity.Authorization.AspNetCore;

public static class AuthorizationExtensions
{
    public static IServiceCollection AddCompanyAuthorization(this IServiceCollection services)
    {
        services.AddSingleton<IAuthorizationPolicyProvider, PermissionPolicyProvider>();
        services.AddSingleton<IAuthorizationHandler, PermissionAuthorizationHandler>();
        services.AddAuthorization();
        return services;
    }
}

public sealed class PermissionPolicyProvider : DefaultAuthorizationPolicyProvider
{
    public PermissionPolicyProvider(Microsoft.Extensions.Options.IOptions<AuthorizationOptions> options) : base(options) { }
    public override async Task<AuthorizationPolicy?> GetPolicyAsync(string policyName)
    {
        return await base.GetPolicyAsync(policyName) ?? new AuthorizationPolicyBuilder()
            .RequireAuthenticatedUser()
            .AddRequirements(new PermissionRequirement(policyName))
            .Build();
    }
}

public sealed class PermissionAuthorizationHandler : AuthorizationHandler<PermissionRequirement>
{
    protected override Task HandleRequirementAsync(AuthorizationHandlerContext context, PermissionRequirement requirement)
    {
        if (context.User.Claims.Any(c => c.Type is "permission" or "permissions" && c.Value == requirement.Permission)) context.Succeed(requirement);
        return Task.CompletedTask;
    }
}
using System.Reflection;
using Company.Identity.Abstractions;

namespace Company.Identity.PermissionDiscovery;

public static class PermissionDiscovery
{
    public static IReadOnlyCollection<PermissionDescriptor> Discover(Assembly assembly)
    {
        ArgumentNullException.ThrowIfNull(assembly);
        var descriptors = new List<PermissionDescriptor>();
        foreach (var type in GetLoadableTypes(assembly))
        {
            var typePermissions = type
                .GetCustomAttributes<RequirePermissionAttribute>(inherit: true)
                .Select(attribute => new PermissionDescriptor(
                    attribute.Name,
                    $"Permission for {type.FullName ?? type.Name}",
                    type.Namespace ?? string.Empty));
            descriptors.AddRange(typePermissions);

            foreach (var method in type.GetMethods(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance | BindingFlags.Static))
            {
                var methodPermissions = method
                    .GetCustomAttributes<RequirePermissionAttribute>(inherit: true)
                    .Select(attribute => new PermissionDescriptor(
                        attribute.Name,
                        $"Permission for {method.DeclaringType?.FullName ?? type.Name}.{method.Name}",
                        type.Namespace ?? string.Empty));
                descriptors.AddRange(methodPermissions);
            }
        }

        return descriptors
            .Where(x => !string.IsNullOrWhiteSpace(x.Name))
            .DistinctBy(x => x.Name, StringComparer.Ordinal)
            .OrderBy(x => x.Name, StringComparer.Ordinal)
            .ToArray();
    }

    private static IEnumerable<Type> GetLoadableTypes(Assembly assembly)
    {
        try
        {
            return assembly.GetTypes();
        }
        catch (ReflectionTypeLoadException exception)
        {
            return exception.Types.Where(x => x is not null)!;
        }
    }
}

