using Identity.Domain;
using Microsoft.EntityFrameworkCore;

namespace Identity.Persistence.EntityFrameworkCore;

public sealed class IdentityDbContext(DbContextOptions<IdentityDbContext> options) : DbContext(options)
{
    public DbSet<User> Users => Set<User>();
    public DbSet<PasswordCredential> PasswordCredentials => Set<PasswordCredential>();
    public DbSet<UserSession> Sessions => Set<UserSession>();
    public DbSet<RefreshTokenRecord> RefreshTokens => Set<RefreshTokenRecord>();
    public DbSet<Role> Roles => Set<Role>();
    public DbSet<Permission> Permissions => Set<Permission>();
    public DbSet<UserPermission> UserPermissions => Set<UserPermission>();
    public DbSet<UserRole> UserRoles => Set<UserRole>();
    public DbSet<RolePermission> RolePermissions => Set<RolePermission>();
    public DbSet<PermissionManifestState> PermissionManifestStates => Set<PermissionManifestState>();
    public DbSet<ExternalIdentityLink> ExternalIdentityLinks => Set<ExternalIdentityLink>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<User>(b =>
        {
            b.HasKey(x => x.Id);
            b.Property(x => x.Id).HasConversion(x => x.Value, x => new UserId(x));
            b.Property(x => x.Username).HasMaxLength(256).IsRequired();
            b.HasIndex(x => x.Username).IsUnique();
            b.Property(x => x.SecurityStamp).HasMaxLength(64).IsRequired();
            b.Ignore(x => x.Roles); b.Ignore(x => x.DirectPermissions);
        });
        modelBuilder.Entity<PasswordCredential>(b =>
        {
            b.HasKey(x => x.UserId);
            b.Property(x => x.UserId).HasConversion(x => x.Value, x => new UserId(x));
            b.Property(x => x.PasswordHash).HasMaxLength(512).IsRequired();
        });
        modelBuilder.Entity<UserSession>(b =>
        {
            b.HasKey(x => x.Id);
            b.Property(x => x.UserId).HasConversion(x => x.Value, x => new UserId(x));
            b.HasIndex(x => new { x.UserId, x.RevokedAt });
            b.HasIndex(x => x.ExpiresAt);
        });
        modelBuilder.Entity<RefreshTokenRecord>(b =>
        {
            b.HasKey(x => x.Id);
            b.Property(x => x.UserId).HasConversion(x => x.Value, x => new UserId(x));
            b.Property(x => x.TokenHash).HasMaxLength(128).IsRequired();
            b.Property(x => x.FamilyId).HasMaxLength(64).IsRequired();
            b.HasIndex(x => x.TokenHash).IsUnique();
            b.HasIndex(x => new { x.FamilyId, x.RevokedAt });
        });
        modelBuilder.Entity<Role>(b =>
        {
            b.HasKey(x => x.Id);
            b.Property(x => x.Id).HasConversion(x => x.Value, x => new RoleId(x));
            b.Property(x => x.Name).HasMaxLength(128).IsRequired(); b.HasIndex(x => x.Name).IsUnique(); b.Ignore(x => x.Permissions);
        });
        modelBuilder.Entity<UserPermission>(b =>
        {
            b.HasKey(x => new { x.UserId, x.PermissionId });
            b.Property(x => x.UserId).HasConversion(x => x.Value, x => new UserId(x));
            b.Property(x => x.PermissionId).HasConversion(x => x.Value, x => new PermissionId(x));
        });
        modelBuilder.Entity<UserRole>(b =>
        {
            b.HasKey(x => new { x.UserId, x.RoleId });
            b.Property(x => x.UserId).HasConversion(x => x.Value, x => new UserId(x));
            b.Property(x => x.RoleId).HasConversion(x => x.Value, x => new RoleId(x));
        });
        modelBuilder.Entity<RolePermission>(b =>
        {
            b.HasKey(x => new { x.RoleId, x.PermissionId });
            b.Property(x => x.RoleId).HasConversion(x => x.Value, x => new RoleId(x));
            b.Property(x => x.PermissionId).HasConversion(x => x.Value, x => new PermissionId(x));
        });
        modelBuilder.Entity<PermissionManifestState>(b =>
        {
            b.HasKey(x => x.ServiceId);
            b.Property(x => x.ServiceId).HasMaxLength(128).IsRequired();
            b.Property(x => x.ServiceName).HasMaxLength(128).IsRequired();
            b.Property(x => x.ManifestVersion).HasMaxLength(64).IsRequired();
            b.HasIndex(x => new { x.ServiceName, x.ManifestVersion });
        });
        modelBuilder.Entity<ExternalIdentityLink>(b =>
        {
            b.HasKey(x => x.Id);
            b.Property(x => x.UserId).HasConversion(x => x.Value, x => new UserId(x));
            b.Property(x => x.Provider).HasMaxLength(128).IsRequired();
            b.Property(x => x.Subject).HasMaxLength(512).IsRequired();
            b.HasIndex(x => new { x.Provider, x.Subject }).IsUnique();
            b.HasIndex(x => x.UserId);
        });
        modelBuilder.Entity<Permission>(b =>
        {
            b.HasKey(x => x.Id);
            b.Property(x => x.Id).HasConversion(x => x.Value, x => new PermissionId(x));
            b.Property(x => x.Name).HasMaxLength(200).IsRequired(); b.HasIndex(x => new { x.ServiceName, x.Name }).IsUnique();
            b.Property(x => x.ServiceName).HasMaxLength(128).IsRequired(); b.Property(x => x.Version).HasMaxLength(64).IsRequired();
        });
    }
}
using Identity.Application;
using Identity.Domain;
using Microsoft.EntityFrameworkCore;

namespace Identity.Persistence.EntityFrameworkCore;

public sealed class EfUserRepository(IdentityDbContext db) : IUserRepository
{
    public Task<User?> FindByUsernameAsync(string username, CancellationToken cancellationToken) => db.Users.SingleOrDefaultAsync(x => x.Username == username, cancellationToken);
    public Task<User?> FindAsync(UserId id, CancellationToken cancellationToken) => db.Users.SingleOrDefaultAsync(x => x.Id == id, cancellationToken);
    public async Task AddAsync(User user, CancellationToken cancellationToken) { await db.Users.AddAsync(user, cancellationToken); await db.SaveChangesAsync(cancellationToken); }
    public async Task SaveAsync(User user, CancellationToken cancellationToken) { db.Users.Update(user); await db.SaveChangesAsync(cancellationToken); }
}

public sealed class EfPasswordCredentialStore(IdentityDbContext db) : IPasswordCredentialStore
{
    public Task<PasswordCredential?> FindAsync(UserId userId, CancellationToken cancellationToken) => db.PasswordCredentials.SingleOrDefaultAsync(x => x.UserId == userId, cancellationToken);
    public async Task SaveAsync(PasswordCredential credential, CancellationToken cancellationToken) { db.PasswordCredentials.Update(credential); await db.SaveChangesAsync(cancellationToken); }
}

public sealed class EfSessionStore(IdentityDbContext db) : ISessionStore
{
    public async Task AddAsync(UserSession session, CancellationToken cancellationToken) { await db.Sessions.AddAsync(session, cancellationToken); await db.SaveChangesAsync(cancellationToken); }
    public Task<UserSession?> FindAsync(Guid id, CancellationToken cancellationToken) => db.Sessions.SingleOrDefaultAsync(x => x.Id == id, cancellationToken);
    public async Task<IReadOnlyCollection<UserSession>> FindForUserAsync(UserId userId, CancellationToken cancellationToken)
        => await db.Sessions.Where(x => x.UserId == userId).ToArrayAsync(cancellationToken);
    public async Task RevokeAsync(UserSession session, DateTimeOffset at, CancellationToken cancellationToken) { session.Revoke(at); db.Sessions.Update(session); await db.SaveChangesAsync(cancellationToken); }
}

public sealed class EfRefreshTokenStore(IdentityDbContext db) : IRefreshTokenStore
{
