        CancellationToken cancellationToken)
    {
        if (!user.IsEnabled || user.IsLocked(clock.UtcNow))
            return AuthenticationResult.Failure("session_invalid");
        var session = new UserSession(
            Guid.NewGuid(),
            user.Id,
            clock.UtcNow,
            clock.UtcNow.AddHours(8),
            user.SecurityStamp);
